80	@RestController
81	@CrossOrigin(exposedHeaders = "errors, content-type")
82	@RequestMapping("/api")
83	public class OwnerRestControllerV1 implements OwnersApi {
84	
85	    /**
86	     * Dedicated audit logger. A successful owner create emits here, independently of the application
87	     * log: first a human-readable line carrying the new owner's id, member id, registration date
88	     * and membership level, then the immutable structured {@code OWNER_CREATED} event (see
89	     * {@link OwnerCreatedEvent}) as a compact JSON object.
90	     */
91	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
92	
93	    /**
94	     * Dedicated notification logger. On a successful owner create a welcome notification is enqueued
95	     * here, emitting a single line carrying the new owner's id and member id.
96	     */
97	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
98	
99	    /**
100	     * Process-wide sequence backing the {@code seq} of the structured {@code OWNER_CREATED} event. It
101	     * is incremented once per successful create so each emitted event carries a strictly larger,
102	     * monotonically increasing sequence number than the one before it.
103	     */
104	    private static final AtomicInteger AUDIT_SEQUENCE = new AtomicInteger();
105	
106	    private final ClinicService clinicService;
107	
108	    private final OwnerMapper ownerMapper;
109	
110	    private final PetMapper petMapper;
111	
112	    private final VisitMapper visitMapper;
113	
114	    /**
115	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
116	     * and a domain containing at least one dot, with no whitespace in any segment.
117	     */
118	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
119	
120	    /**
121	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email address
122	     * is on this blocklist (compared case-insensitively on the domain, the part after the final
123	     * {@code '@'}) is rejected with a 400 Bad Request.
124	     */
125	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
126	        "mailinator.com",
127	        "tempmail.com",
128	        "guerrillamail.com");
129	
130	    /**
131	     * Required national-number length per E.164 country code. A normalized telephone whose country
132	     * code appears here must carry exactly this many national digits after the code; Australia
133	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
134	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
135	     */
136	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
137	
138	    /**
139	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
140	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
141	     */
142	    private static final int MAX_OWNERS_PER_CITY = 50;
143	
144	    /**
145	     * Lower bound of the per-city capacity-warning band. When a city already holds at least this many
146	     * but fewer than {@value #MAX_OWNERS_PER_CITY} owners it is approaching capacity, and a create in
147	     * that city is flagged ({@code capacityWarning} true); the hard rejection at
148	     * {@value #MAX_OWNERS_PER_CITY} is unaffected.
149	     */
150	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
151	
152	    /**
153	     * Maximum number of owners that may be registered on a single day (by registration date). A create
154	     * attempted once this many owners already carry today's registration date is rejected with a
155	     * 429 Too Many Requests.
156	     */
157	    private static final int MAX_OWNERS_PER_DAY = 100;
158	
159	    /**
160	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
161	     * owners already carry the new owner's registration date, the created owner is flagged
162	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
163	     */
164	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
165	
166	    /**
167	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
168	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
169	     */
170	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
171	        "ST", "STREET",
172	        "RD", "ROAD",
173	        "AVE", "AVENUE");
174	
175	    /**
176	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
177	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
178	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
179	     * 4-digit postcode.
180	     */
181	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
182	        "NSW", new int[] {2000, 2099},
183	        "VIC", new int[] {3000, 3099},
184	        "QLD", new int[] {4000, 4099});
185	
186	    /**
187	     * Name of the request header that carries the client-supplied idempotency key for an owner create.
188	     * When a create repeats with a key already seen, the originally created owner is returned with
189	     * {@code 200 OK} instead of a second owner being created.
190	     */
191	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
192	
193	    /**
194	     * Remembers, per idempotency key, the id of the owner created by the first request that carried that
195	     * key, so a later create repeating the same key can return the original owner instead of creating a
196	     * duplicate. The key space is the client-supplied {@code Idempotency-Key} header value.
197	     */
198	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
199	
200	    public OwnerRestControllerV1(ClinicService clinicService,
201	                                 OwnerMapper ownerMapper,
202	                                 PetMapper petMapper,
203	                                 VisitMapper visitMapper) {
204	        this.clinicService = clinicService;
205	        this.ownerMapper = ownerMapper;
206	        this.petMapper = petMapper;
207	        this.visitMapper = visitMapper;
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
213	        Collection<Owner> owners;
214	        if (lastName != null) {
215	            owners = this.clinicService.findOwnerByLastName(lastName);
216	        } else {
217	            owners = this.clinicService.findAllOwners();
218	        }
219	        if (owners.isEmpty()) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
223	    }
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Override
227	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
228	        Owner owner = this.clinicService.findOwnerById(ownerId);
229	        if (owner == null) {
230	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	        }
232	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
238	        String idempotencyKey = currentIdempotencyKey();
239	        OwnerDto replayed = replayIfSeen(idempotencyKey);
240	        if (replayed != null) {
241	            return new ResponseEntity<>(replayed, HttpStatus.OK);
242	        }
243	        validateRequiredFields(ownerFieldsDto);
244	        HttpHeaders headers = new HttpHeaders();
245	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
246	        rejectFutureRegistrationDate(owner.getRegistrationDate());
247	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
248	        owner.setRegistrationDate(registrationDate);
249	        requireDailyCapacity(registrationDate);
250	        long cityOwnerCount = countOwnersInCity(owner.getCity());
251	        requireCityHasCapacity(owner.getCity(), cityOwnerCount);
252	        owner.setCapacityWarning(isApproachingCityCapacity(cityOwnerCount));
253	        validatePostcode(owner);
254	        applyAddress(owner, ownerFieldsDto);
255	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
256	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
257	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
258	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
259	        requireUniqueIdentity(owner);
260	        flagPossibleDuplicate(owner, declaredHouseholdMember);
261	        owner.setMemberId(deduplicateMemberId(owner.buildMemberId()));
262	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
263	        stampHouseholdSize(owner);
264	        capMembershipLevelToHousehold(owner);
265	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
266	        this.clinicService.saveOwner(owner);
267	        rememberCreate(idempotencyKey, owner);
268	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
269	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
270	        emitOwnerCreatedEvent(owner);
271	        enqueueWelcomeNotification(owner);
272	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
273	        headers.setLocation(UriComponentsBuilder.newInstance()
274	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
275	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
276	    }
277	
278	    /**
279	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@link #AUDIT} logger as a
280	     * compact JSON object, alongside the human-readable audit line. The event's {@code seq} is drawn
281	     * from the process-wide {@link #AUDIT_SEQUENCE}, so it strictly increases across creates, and it
282	     * carries both the owner's id and its current primary identifier via
283	     * {@link #primaryIdentifier(Owner)}.
284	     *
285	     * @param owner the owner that was just created and saved
286	     */
287	    private void emitOwnerCreatedEvent(Owner owner) {
288	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQUENCE.incrementAndGet(),
289	            owner.getId(), owner.getMemberId(), owner.getMembershipLevel(), owner.getOwnerSegment());
290	        AUDIT.info(event.toJson());
291	    }
292	
293	    /**
294	     * Enqueues a welcome notification for a just-created owner by emitting a single line to the
295	     * {@link #NOTIFY} logger carrying the owner's id and its member id.
296	     *
297	     * @param owner the owner that was just created and saved
298	     */
299	    private void enqueueWelcomeNotification(Owner owner) {
300	        NOTIFY.info("Welcome owner: id={} memberId={}", owner.getId(), owner.getMemberId());
301	    }
302	
303	    /**
304	     * The immutable structured event emitted on a successful owner create, at schema version 2.
305	     * {@code seq} is the process-wide monotonically increasing sequence across creates; {@code ownerId}
306	     * is the new owner's id; {@code memberId} carries the owner's version-2 member id;
307	     * {@code membershipLevel} is the owner's membership level; {@code ownerSegment} is the owner's
308	     * segment recomputed from the version-2 owner (its plain-region locality and membership level). It
309	     * serializes to a compact JSON object whose {@code event} is always {@value #EVENT_TYPE} and whose
310	     * {@code schemaVersion} is always {@value #SCHEMA_VERSION}.
311	     *
312	     * @param seq the monotonically increasing create sequence number
313	     * @param ownerId the created owner's id
314	     * @param memberId the owner's version-2 member id
315	     * @param membershipLevel the owner's membership level
316	     * @param ownerSegment the owner's segment recomputed from the version-2 owner
317	     */
318	    private record OwnerCreatedEvent(int seq, Integer ownerId, String memberId, Integer membershipLevel,
319	                                     String ownerSegment) {
320	
321	        /** The fixed {@code event} discriminator carried by every emitted event. */
322	        private static final String EVENT_TYPE = "OWNER_CREATED";
323	
324	        /** The fixed schema version carried by every emitted event. */
325	        private static final int SCHEMA_VERSION = 2;
326	
327	        /** Shared, thread-safe mapper used only to serialize the event to its JSON form. */
328	        private static final ObjectMapper MAPPER = JsonMapper.builder().build();
329	
330	        /**
331	         * Serializes this event to its compact JSON form
332	         * {@code {seq, ownerId, memberId, membershipLevel, ownerSegment, event, schemaVersion}}, with
333	         * the fields in that order.
334	         *
335	         * @return the event as a JSON object string
336	         */
337	        private String toJson() {
338	            Map<String, Object> fields = new LinkedHashMap<>();
339	            fields.put("seq", this.seq);
340	            fields.put("ownerId", this.ownerId);
341	            fields.put("memberId", this.memberId);
342	            fields.put("membershipLevel", this.membershipLevel);
343	            fields.put("ownerSegment", this.ownerSegment);
344	            fields.put("event", EVENT_TYPE);
345	            fields.put("schemaVersion", SCHEMA_VERSION);
346	            return MAPPER.writeValueAsString(fields);
347	        }
348	    }
349	
350	    /**
351	     * Reads the client-supplied idempotency key from the current request's {@code Idempotency-Key}
352	     * header. Returns {@code null} when the header is absent or blank (the create is not idempotent),
353	     * or when no servlet request is bound to the current thread.
354	     *
355	     * <p>The header is read from the bound request rather than taken as a {@code @RequestHeader} method
356	     * parameter because {@code addOwner}'s signature is fixed by the generated {@link OwnersApi}
357	     * interface and cannot carry an extra parameter.
358	     *
359	     * @return the trimmed idempotency key, or {@code null} when none was supplied
360	     */
361	    private String currentIdempotencyKey() {
362	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes) {
363	            String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
364	            if (StringUtils.hasText(key)) {
365	                return key.trim();
366	            }
367	        }
368	        return null;
369	    }
370	
371	    /**
372	     * Returns the owner originally created under the given idempotency key, so a create repeating a
373	     * key already seen replays the first result instead of creating a duplicate. Yields {@code null}
374	     * when there is no key, the key has not been seen, or the remembered owner no longer exists (in
375	     * which case the create proceeds normally).
376	     *
377	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
378	     * @return the originally created owner as a DTO, or {@code null} when there is nothing to replay
379	     */
380	    private OwnerDto replayIfSeen(String idempotencyKey) {
381	        if (idempotencyKey == null) {
382	            return null;
383	        }
384	        Integer existingId = idempotentCreates.get(idempotencyKey);
385	        if (existingId == null) {
386	            return null;
387	        }
388	        Owner existing = this.clinicService.findOwnerById(existingId);
389	        return existing == null ? null : ownerMapper.toOwnerDto(existing);
390	    }
391	
392	    /**
393	     * Remembers the id of a just-created owner against the idempotency key that produced it, so a later
394	     * create repeating the same key can be replayed by {@link #replayIfSeen}. A {@code null} key (the
395	     * create was not idempotent) is ignored.
396	     *
397	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when none was supplied
398	     * @param owner the owner that was just created and saved
399	     */
400	    private void rememberCreate(String idempotencyKey, Owner owner) {
401	        if (idempotencyKey != null) {
402	            idempotentCreates.put(idempotencyKey, owner.getId());
403	        }
404	    }
405	
406	    /**
407	     * Rejects a create whose supplied registration date is later than the server's current date. A
408	     * registration may be back-dated but never post-dated, so a future date is treated as a client
409	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
410	     * server date.
411	     *
412	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
413	     *     client omitted it
414	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
415	     */
416	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
417	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
418	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
419	        }
420	    }
421	
422	    /**
423	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
424	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
425	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
426	     * existed prior to this create.
427	     *
428	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
429	     *     a business day
430	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
431	     *     registered on that business day
432	     */
433	    private void requireDailyCapacity(LocalDate registrationDate) {
434	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
435	            throw new DailyOwnerLimitException(registrationDate);
436	        }
437	    }
438	
439	    /**
440	     * Counts the existing owners whose registration date equals the given business-day date. This is
441	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
442	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
443	     * the bulk-signup warning.
444	     *
445	     * @param registrationDate the effective business-day registration date to count against
446	     * @return the number of pre-existing owners registered on that date
447	     */
448	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
449	        return this.clinicService.findAllOwners().stream()
450	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
451	            .count();
452	    }
453	
454	    /**
455	     * Rejects an owner whose city already contains the maximum allowed number of owners
456	     * ({@value #MAX_OWNERS_PER_CITY}). The count is supplied by {@link #countOwnersInCity(String)} and
457	     * reflects only the owners that existed prior to this create.
458	     *
459	     * @param city the city of the owner being created
460	     * @param cityOwnerCount the number of pre-existing owners already in that city
461	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
462	     */
463	    private void requireCityHasCapacity(String city, long cityOwnerCount) {
464	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
465	            throw new CityOwnerLimitException(city);
466	        }
467	    }
468	
469	    /**
470	     * Counts the existing owners whose city equals the given city, compared case-insensitively. This is
471	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to this
472	     * create. It is the single definition of the per-city count shared by the city hard-limit rule and
473	     * the approaching-capacity warning.
474	     *
475	     * @param city the city of the owner being created
476	     * @return the number of pre-existing owners in that city
477	     */
478	    private long countOwnersInCity(String city) {
479	        return this.clinicService.findAllOwners().stream()
480	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
481	            .count();
482	    }
483	
484	    /**
485	     * Whether a city holding the given number of owners is approaching the per-city capacity limit: at
486	     * least {@value #CITY_CAPACITY_WARNING_THRESHOLD} but fewer than {@value #MAX_OWNERS_PER_CITY}. A
487	     * create in such a city is flagged ({@code capacityWarning} true); the hard rejection at
488	     * {@value #MAX_OWNERS_PER_CITY} is unaffected.
489	     *
490	     * @param cityOwnerCount the number of pre-existing owners already in the city
491	     * @return whether the city is in the 40-49 approaching-capacity band
492	     */
493	    private boolean isApproachingCityCapacity(long cityOwnerCount) {
494	        return cityOwnerCount >= CITY_CAPACITY_WARNING_THRESHOLD && cityOwnerCount < MAX_OWNERS_PER_CITY;
495	    }
496	
497	    /**
498	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
499	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
500	     * schema) that must fall within the inclusive range permitted for the region derived from the
501	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
502	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
503	     *
504	     * @param owner the owner being created, with its city and postcode set
505	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
506	     */
507	    private void validatePostcode(Owner owner) {
508	        String postcode = owner.getPostcode();
509	        if (postcode == null) {
510	            return;
511	        }
512	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
513	        if (range == null) {
514	            return;
515	        }
516	        int value = Integer.parseInt(postcode);
517	        if (value < range[0] || value > range[1]) {
518	            throw new InvalidOwnerFieldsException(List.of("postcode"));
519	        }
520	    }
521	
522	    /**
523	     * Counts the existing owners that already share the given first name and last name, compared
524	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
525	     * owners that existed prior to this create.
526	     *
