582	    /**
583	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
584	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
585	     * what gets stored and returned.
586	     *
587	     * @param telephone the raw telephone value from the request
588	     * @return the normalized E.164 telephone number
589	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
590	     */
591	    private String normalizeTelephone(String telephone) {
592	        String e164 = toE164(telephone);
593	        if (e164 == null) {
594	            throw new InvalidOwnerFieldsException(List.of("telephone"));
595	        }
