599	    /**
600	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
601	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
602	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
603	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
604	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
605	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
606	     *
607	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
608	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
609	     *
610	     * @param telephone the raw telephone value, possibly {@code null}
611	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
612	     */
613	    private String toE164(String telephone) {
614	        if (telephone == null) {
615	            return null;
616	        }
617	        String cleaned = telephone.replaceAll("[ \\-()]", "");
618	        String digits;
619	        if (cleaned.startsWith("+")) {
620	            digits = cleaned.substring(1);
621	        } else {
622	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
623	            digits = "61" + national;
624	        }
625	        if (!digits.matches("[0-9]{8,15}")) {
626	            return null;
627	        }
628	        if (!nationalNumberLengthValid(digits)) {
629	            return null;
630	        }
631	        return "+" + digits;
632	    }
633	
634	    /**
635	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
636	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
637	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
638	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
639	     * accepted, leaving only the generic total-length rule to apply.
640	     *
641	     * @param digits the E.164 digits without the leading {@code '+'}
642	     * @return {@code true} if the national-number length matches the country code's requirement
643	     */
644	    private boolean nationalNumberLengthValid(String digits) {
645	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
646	            String code = entry.getKey();
647	            if (digits.startsWith(code)) {
648	                return digits.length() - code.length() == entry.getValue();
649	            }
650	        }
651	        return true;
652	    }
