654	    /**
655	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
656	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
657	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
658	     * returned lower-cased.
659	     *
660	     * @param email the raw email value from the request, possibly {@code null}
661	     * @return the lower-cased email, or {@code null} when none was supplied
662	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
663	     *     its domain is on the disposable-domain blocklist
664	     */
665	    private String normalizeEmail(String email) {
666	        if (!StringUtils.hasText(email)) {
667	            return null;
668	        }
669	        String trimmed = email.trim();
670	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
671	            throw new InvalidOwnerFieldsException(List.of("email"));
672	        }
673	        String normalized = trimmed.toLowerCase(Locale.ROOT);
674	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
675	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
676	            throw new InvalidOwnerFieldsException(List.of("email"));
677	        }
678	        return normalized;
679	    }
