681	    /**
682	     * Rejects an owner whose whole identity key is already used by an existing (non-deleted) owner.
683	     * This is the single consolidated duplicate check: the identity key
684	     * ({@link Owner#getIdentityKey()}) is the lower-case SHA-256 hex of the owner's normalized
685	     * telephone, lower-cased email (empty when absent) and the Soundex of its last name joined with
686	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
687	     * owner's. Because the telephone is part of the key, two owners sharing a last name and postcode
688	     * but carrying different telephones have different identity keys and are both allowed (the second
689	     * is flagged a soft match by {@link #flagPossibleDuplicate}). Owners flagged deleted are ignored.
690	     *
691	     * @param owner the owner being created, with its normalized telephone, email and last name set
692	     * @throws DuplicateIdentityException if another owner already has this identity key
693	     */
694	    private void requireUniqueIdentity(Owner owner) {
695	        String identityKey = owner.getIdentityKey();
696	        boolean inUse = this.clinicService.findAllOwners().stream()
697	            .filter(existing -> !existing.isDeleted())
698	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
699	        if (inUse) {
700	            throw new DuplicateIdentityException(identityKey);
701	        }
702	    }
