704	    /**
705	     * De-duplicates a newly computed member id against the ids already held by existing owners. When
706	     * the computed id is unique it is returned unchanged. When it collides with an existing owner's
707	     * {@code memberId}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that makes
708	     * the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and so on),
709	     * and that de-duplicated id is returned.
710	     *
711	     * @param memberId the freshly computed member id to de-duplicate
712	     * @return a member id not held by any existing owner
713	     */
714	    private String deduplicateMemberId(String memberId) {
715	        Set<String> inUse = this.clinicService.findAllOwners().stream()
716	            .map(Owner::getMemberId)
717	            .filter(Objects::nonNull)
718	            .collect(Collectors.toSet());
719	        if (!inUse.contains(memberId)) {
720	            return memberId;
721	        }
722	        int n = 2;
723	        String candidate;
724	        do {
725	            candidate = memberId + "-" + n;
726	            n++;
727	        } while (inUse.contains(candidate));
728	        return candidate;
729	    }
