731	    /**
732	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
733	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
734	     * but it shares an existing owner's last-name {@linkplain Soundex#encode(String) Soundex} and postcode
735	     * (both present and equal) while carrying a different identity key. When such an existing owner is
736	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
737	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
738	     * is false and {@code possibleDuplicateOf} is left unset.
739	     *
740	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
741	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
742	     *
743	     * @param owner the owner being created, with its normalized telephone, email, last name and postcode set
744	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
745	     */
746	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
747	        if (declaredHouseholdMember || owner.getPostcode() == null) {
748	            owner.setPossibleDuplicate(false);
749	            return;
750	        }
751	        String identityKey = owner.getIdentityKey();
752	        String soundex = Soundex.encode(owner.getLastName());
753	        Integer matchId = this.clinicService.findAllOwners().stream()
754	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName()))
755	                && owner.getPostcode().equals(existing.getPostcode())
756	                && !identityKey.equals(existing.getIdentityKey()))
757	            .map(Owner::getId)
758	            .min(Integer::compareTo)
759	            .orElse(null);
760	        owner.setPossibleDuplicate(matchId != null);
761	        owner.setPossibleDuplicateOf(matchId);
762	    }
