764	    /**
765	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
766	     * the household - the existing owners that share the deterministic {@code householdId} and the new
767	     * one - so the shared size can be read back from any of them. The count is the number of existing
768	     * members plus the owner being created.
769	     *
770	     * @param owner the owner being created, with its deterministic {@code householdId} already set
771	     */
772	    private void stampHouseholdSize(Owner owner) {
773	        List<Owner> members = householdMembers(owner);
774	        int householdSize = members.size() + 1;
775	        owner.setHouseholdSize(householdSize);
