782	    /**
783	     * The existing owners that belong to the same household as the given owner - those that share its
784	     * deterministic {@code householdId}. This is the single definition of "who is in this household",
785	     * shared by the household-size stamp and the membership-level cap. The owner being created is not
786	     * among them (it has not been saved yet); soft-deleted owners are included, so callers that need
787	     * only live members filter them out themselves.
788	     *
789	     * @param owner the owner being created, with its deterministic {@code householdId} already set
790	     * @return the existing same-household owners
791	     */
792	    private List<Owner> householdMembers(Owner owner) {
793	        String householdId = owner.getHouseholdId();
