799	    /**
800	     * Caps the new owner's membership level so it cannot exceed one above the current maximum
801	     * membership level among the existing members of its household - the non-deleted owners that share
802	     * the deterministic {@code householdId}. The new owner's level is lowered to that ceiling only when
803	     * its derived level sits above it; otherwise it is left to be derived normally. When the household
804	     * has no existing member no cap applies and the level is left untouched.
805	     *
806	     * @param owner the owner being created, with its deterministic {@code householdId} and
807	     *     {@code householdSize} already set
808	     */
809	    private void capMembershipLevelToHousehold(Owner owner) {
810	        OptionalInt maxMemberLevel = householdMembers(owner).stream()
811	            .filter(existing -> !existing.isDeleted())
812	            .mapToInt(Owner::getMembershipLevel)
813	            .max();
814	        if (maxMemberLevel.isEmpty()) {
815	            return;
816	        }
817	        int cap = maxMemberLevel.getAsInt() + 1;
818	        if (owner.getMembershipLevel() > cap) {
819	            owner.setMembershipLevel(cap);
820	        }
821	    }
