823	    /**
824	     * Computes the deterministic, shared version-2 household identifier for a last name and postcode: the
825	     * first 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
826	     * {@code 'V2' + '|' + normalizedLastName + '|' + postcode}. The fixed {@code 'V2'} version tag (see
827	     * {@link Owner#IDENTITY_VERSION_TAG}) is mixed in so the identifier differs from the value produced
828	     * under version 1. The last name is normalized (case-insensitive, whitespace-collapsed) and an
829	     * absent postcode contributes an empty string, so every owner that shares a last name and postcode
830	     * computes the same identifier and therefore the same household.
831	     *
832	     * @param lastName the last name of the household
833	     * @param postcode the postcode of the household, possibly {@code null}
834	     * @return the 12-character upper-case hex household identifier
835	     */
836	    private String computeHouseholdId(String lastName, String postcode) {
837	        String key = Owner.IDENTITY_VERSION_TAG + "|" + normalizeForHousehold(lastName)
838	            + "|" + (postcode == null ? "" : postcode);
839	        try {
840	            byte[] digest = MessageDigest.getInstance("SHA-256")
841	                .digest(key.getBytes(StandardCharsets.UTF_8));
842	            StringBuilder hex = new StringBuilder(12);
843	            for (int i = 0; i < 6; i++) {
844	                hex.append(String.format("%02X", digest[i]));
845	            }
846	            return hex.toString();
847	        } catch (NoSuchAlgorithmException e) {
848	            throw new IllegalStateException("SHA-256 algorithm not available", e);
849	        }
850	    }
