864	    /**
865	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
866	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
867	     * value yields an empty string.
868	     *
869	     * @param value the raw value, possibly {@code null}
870	     * @return the trimmed, whitespace-collapsed value
871	     */
872	    private String collapseWhitespace(String value) {
873	        if (value == null) {
874	            return "";
875	        }
876	        return value.trim().replaceAll("\\s+", " ");
877	    }
