879	    /**
880	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
881	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
882	     * is upper-cased, and common street-type abbreviations are expanded as whole words
883	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
884	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
885	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
886	     *
887	     * @param address the raw address value, possibly {@code null}
888	     * @return the normalized address
889	     */
890	    private String normalizeAddress(String address) {
891	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
892	        if (collapsed.isEmpty()) {
893	            return "";
894	        }
895	        String[] tokens = collapsed.split(" ");
896	        StringBuilder normalized = new StringBuilder();
897	        for (int i = 0; i < tokens.length; i++) {
898	            if (i > 0) {
899	                normalized.append(' ');
900	            }
901	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
902	        }
903	        return normalized.toString();
904	    }
