906	    /**
907	     * Applies the owner's address from the request, preferring the structured form over the flat one.
908	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
909	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
910	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
911	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
912	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
913	     * the structured address when present, falling back to the flat address.
914	     *
915	     * @param owner the owner being created
916	     * @param ownerFieldsDto the submitted owner fields
917	     */
918	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
919	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
920	        if (StringUtils.hasText(line1)) {
921	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
922	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
923	            owner.setAddressLine1(line1);
924	            owner.setAddressLine2(normalizedLine2);
925	            owner.setAddress(composeAddress(line1, normalizedLine2));
926	        } else {
927	            owner.setAddressLine1(null);
928	            owner.setAddressLine2(null);
929	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
930	        }
931	    }
