933	    /**
934	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
935	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
936	     * appended when the second line is present.
937	     *
938	     * @param line1 the normalized first address line
939	     * @param line2 the normalized second address line, or {@code null} when absent
940	     * @return the composed address string
941	     */
942	    private String composeAddress(String line1, String line2) {
943	        return line2 == null ? line1 : line1 + " " + line2;
944	    }
