232	    /**
233	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
234	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
235	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
236	     * split by taking its leading digit as the (minimal) country code.
237	     */
238	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
239	
240	    /**
241	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
242	     * single space, then the national digits grouped in threes from the left (e.g. the stored
243	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
244	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
245	     * digit string.
246	     *
247	     * @return the human-readable telephone, or the stored value when it cannot be formatted
248	     */
249	    public String getTelephoneDisplay() {
250	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
251	            return this.telephone;
252	        }
253	        String digits = this.telephone.substring(1);
254	        String countryCode = extractCountryCode(digits);
255	        String national = digits.substring(countryCode.length());
256	        StringBuilder display = new StringBuilder("+").append(countryCode);
257	        for (int i = 0; i < national.length(); i += 3) {
258	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
259	        }
260	        return display.toString();
261	    }
262	
263	    /**
264	     * Splits the country code off an E.164 digit string (country code followed by national digits,
265	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
266	     * whose required national-number length matches the remaining digits is preferred; failing that,
267	     * the leading digit is used as the country code.
268	     *
269	     * @param digits the E.164 digits without the leading {@code '+'}
270	     * @return the country-code portion of {@code digits}
271	     */
272	    private static String extractCountryCode(String digits) {
273	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
274	            String code = entry.getKey();
275	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
276	                return code;
277	            }
278	        }
279	        return digits.substring(0, 1);
280	    }
