338	    /**
339	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the two fiscal-year
340	     * digits of the {@link #getRegistrationDate() business-day-adjusted registration date}. The fiscal
341	     * year starts on 1 July and is named by the calendar year in which it ends, so a registration date
342	     * on or after 1 July belongs to the following calendar year's fiscal year (e.g. {@code 2026-07-01}
343	     * is {@code 'FY27'}) while an earlier date stays in the current one (e.g. {@code 2026-06-15} is
344	     * {@code 'FY26'}). This is the plain, user-facing fiscal year; it never carries the {@code 'V2'}
345	     * tag that the version-2 identifiers mix into their region. Returns {@code null} when no
346	     * registration date is available.
347	     *
348	     * @return the fiscal year, or {@code null} when it cannot be derived
349	     */
350	    public String getFiscalYear() {
351	        if (this.registrationDate == null) {
352	            return null;
353	        }
354	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
355	    }
356	
357	    /**
358	     * The fiscal year a date falls in, as a full calendar year. The fiscal year starts on 1 July and
359	     * is named by the calendar year in which it ends: a date in July through December belongs to the
360	     * next calendar year's fiscal year, while January through June stays in the current one.
361	     *
362	     * @param date the date to classify
363	     * @return the fiscal year as a four-digit calendar year
364	     */
365	    private static int fiscalYearOf(LocalDate date) {
366	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
367	    }
368	
369	    /**
370	     * The single Luhn check digit (0-9) computed over the digits contained in the given value.
371	     * Non-digit characters (such as the letter region and hex characters) are ignored. This is the
372	     * {@code CHK} segment of the {@link #getMemberId() member id}, computed over the digits of its
373	     * {@code <REGION><FY><HASH8>} prefix.
374	     *
375	     * @param value the value whose digits the check digit is computed over
376	     * @return the Luhn check digit
377	     */
378	    private static int luhnCheckDigit(String value) {
379	        int sum = 0;
380	        boolean dbl = true;
381	        for (int i = value.length() - 1; i >= 0; i--) {
382	            char c = value.charAt(i);
383	            if (c < '0' || c > '9') {
384	                continue;
385	            }
386	            int d = c - '0';
387	            if (dbl) {
388	                d *= 2;
389	                if (d > 9) {
390	                    d -= 9;
391	                }
392	            }
393	            sum += d;
394	            dbl = !dbl;
395	        }
396	        return (10 - (sum % 10)) % 10;
397	    }
