399	    /**
400	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
401	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
402	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
403	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
404	     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
405	     * tenure, the tenure points are never awarded at create time.
406	     *
407	     * @return the membership points, a non-negative integer
408	     */
409	    public Integer getMembershipPoints() {
410	        int points = 0;
411	        boolean hasEmail = this.email != null && !this.email.isBlank();
412	        if (hasEmail) {
413	            points += 2;
414	        }
415	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
416	        if (hasNoNamesakes) {
417	            points += 1;
418	        }
419	        if (this.householdSize != null && this.householdSize >= 3) {
420	            points += 2;
421	        }
422	        Long tenureFiscalYears = getTenureFiscalYears();
423	        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
424	            points += 3;
425	        }
426	        return points;
427	    }
