448	    /**
449	     * The owner's numeric membership level derived purely from the {@link #getMembershipPoints()
450	     * membership points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and
451	     * level 4 for 6 or more points. This is the uncapped level, before any household-level cap.
452	     *
453	     * @return the derived membership level, an integer from 1 to 4
454	     */
455	    public Integer deriveMembershipLevel() {
456	        int points = getMembershipPoints();
457	        if (points <= 1) {
458	            return 1;
459	        }
460	        if (points <= 3) {
461	            return 2;
462	        }
463	        if (points <= 5) {
464	            return 3;
465	        }
466	        return 4;
467	    }
