520	     *
521	     * @return the owner segment string
522	     */
523	    public String getOwnerSegment() {
524	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
525	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
526	        return tier + "_" + area;
