529	    /**
530	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
531	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
532	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
533	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
534	     * the same region for known cities but disambiguates cities that share a name.
535	     *
536	     * @return the canonical region string, or {@code 'UNKNOWN'}
537	     */
538	    private String deriveRegion() {
539	        String region = regionFromPostcode();
540	        if (region != null) {
541	            return region;
542	        }
543	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
544	    }
