546	    /**
547	     * The version-2 region code used inside the identifiers: the plain region ({@link #deriveRegion()})
548	     * with the fixed {@link #IDENTITY_VERSION_TAG 'V2'} version tag mixed in (e.g. {@code 'NSWV2'}). This
549	     * is the region that appears inside the member id and is hashed into the identity key and household
550	     * id; it is never surfaced as the owner's locality, timezone or segment, which stay on the plain
551	     * region.
552	     *
553	     * @return the version-2 region code
554	     */
555	    private String identityRegion() {
556	        return deriveRegion() + IDENTITY_VERSION_TAG;
557	    }
558	
559	    /**
560	     * Builds this owner's version-2 member id, formatted {@code '<REGION><FY><HASH8><CHK>'}.
561	     * {@code REGION} is the version-2 region code ({@link #identityRegion()}): the region derived from
562	     * the postcode (falling back to the city, then {@code 'UNKNOWN'}; see {@link #deriveRegion()}) with
563	     * the fixed {@code 'V2'} tag mixed in (e.g. {@code 'NSWV2'}). {@code FY} is the two-digit fiscal year
564	     * of the {@link #getRegistrationDate() registration date} (the fiscal year starts on 1 July; see
565	     * {@link #fiscalYearOf(LocalDate)}); {@code HASH8} is the first 8 upper-case hexadecimal characters
566	     * of the SHA-256 digest of the owner's normalized telephone concatenated with its last name; and
567	     * {@code CHK} is a single Luhn check digit over the digits of the {@code <REGION><FY><HASH8>} prefix
568	     * (e.g. {@code 'NSWV2261A2B3C4D1'}). It carries no sequence number, so it is a pure function of the
569	     * owner's region, fiscal year, telephone and last name. Call this once at create time and store the
570	     * result via {@link #setMemberId(String)}.
571	     *
572	     * @return the assembled version-2 member id
573	     */
574	    public String buildMemberId() {
575	        String base = identityRegion()
576	            + String.format("%02d", fiscalYearOf(this.registrationDate) % 100)
577	            + sha256Hex8(this.telephone + this.getLastName());
578	        return base + luhnCheckDigit(base);
579	    }
