766	    /**
767	     * Whether the owner's email domain is <em>disposable-adjacent</em>: it shares the second-level name
768	     * of a known disposable mail provider ({@link #DISPOSABLE_EMAIL_DOMAINS}) without necessarily being
769	     * an exact match. This catches the common evasions of the exact-match create-time block - a subdomain
770	     * of a disposable provider (e.g. {@code mail.mailinator.com}) and a sibling top-level domain of one
771	     * (e.g. {@code mailinator.net}) - both of which resolve to the same second-level label
772	     * (e.g. {@code mailinator}). The comparison is case-insensitive. An absent or malformed email is not
773	     * disposable-adjacent.
774	     *
775	     * @return whether the owner's email domain is adjacent to a known disposable provider
776	     */
777	    private boolean isDisposableAdjacentEmail() {
778	        if (this.email == null || this.email.isBlank()) {
779	            return false;
780	        }
781	        int at = this.email.lastIndexOf('@');
782	        if (at < 0 || at == this.email.length() - 1) {
783	            return false;
784	        }
785	        String base = secondLevelLabel(this.email.substring(at + 1).toLowerCase(Locale.ROOT));
786	        if (base.isEmpty()) {
787	            return false;
788	        }
789	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
790	            if (base.equals(secondLevelLabel(disposable))) {
791	                return true;
792	            }
793	        }
794	        return false;
795	    }
