837	    /**
838	     * Resolves the effective registration date and rolls it onto a business day. An absent
839	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
840	     * The resulting date is then rolled forward so it never falls on a weekend or a listed public
841	     * holiday: starting from the effective date, the date advances one day at a time while it lands
842	     * on a Saturday, a Sunday, or a date in {@link #PUBLIC_HOLIDAYS}, stopping on the first
843	     * non-holiday business day. A date already on a business day is returned unchanged.
844	     *
845	     * <p>This is the single definition of both the defaulting and the business-day roll, used
846	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
847	     * stamps the owner and by the create endpoint that counts owners per business day.
848	     *
849	     * @param supplied the registration date from the request, or {@code null} when none was supplied
850	     * @return the effective registration date, guaranteed to fall on a non-holiday business day
851	     */
852	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
853	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
854	        while (!isBusinessDay(effective)) {
855	            effective = effective.plusDays(1);
856	        }
857	        return effective;
858	    }
859	
860	    /**
861	     * The fixed list of public holidays that the registration date rolls past, alongside weekends.
862	     */
863	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
864	        LocalDate.of(2026, 1, 1),
865	        LocalDate.of(2026, 1, 26),
866	        LocalDate.of(2026, 4, 25),
867	        LocalDate.of(2026, 12, 25),
868	        LocalDate.of(2026, 12, 28));
869	
870	    /**
871	     * A business day is any date that is neither a weekend day nor a listed public holiday.
872	     */
873	    private static boolean isBusinessDay(LocalDate date) {
874	        DayOfWeek day = date.getDayOfWeek();
875	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
876	    }
