17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Locale;
20	
21	/**
22	 * American Soundex phonetic encoder: a self-contained, stateless {@code String -> String} algorithm
23	 * for comparing names by sound. It is used both to derive an owner's identity key and to match
24	 * similar-sounding last names when flagging soft-duplicate owners, so it lives here in the shared
25	 * util package rather than on any one entity or controller.
26	 */
27	public abstract class Soundex {
28	
29	    /**
30	     * Maps each letter {@code A}-{@code Z} to its American Soundex code digit, where {@code '0'}
31	     * marks the non-coded letters (the vowels plus {@code H}, {@code W} and {@code Y}). Indexed by
32	     * {@code letter - 'A'}.
33	     */
34	    private static final char[] MAPPING = "01230120022455012623010202".toCharArray();
35	
36	    /**
37	     * The American Soundex code of a name: its first letter followed by three code digits derived
38	     * from the remaining letters (B/F/P/V=1, C/G/J/K/Q/S/X/Z=2, D/T=3, L=4, M/N=5, R=6; the vowels
39	     * plus H, W and Y are not coded), right-padded with zeros to exactly four characters. Adjacent
40	     * letters sharing a code (including when separated only by H or W) contribute a single digit,
41	     * while letters separated by a vowel are coded twice. Non-letters are ignored and the comparison
42	     * is case-insensitive. A {@code null} or letter-free value yields an empty string.
43	     *
44	     * @param value the name to encode, possibly {@code null}
45	     * @return the four-character Soundex code, or an empty string when there are no letters
46	     */
47	    public static String encode(String value) {
48	        if (value == null) {
49	            return "";
50	        }
51	        String clean = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
52	        if (clean.isEmpty()) {
53	            return "";
54	        }
55	        char[] out = {'0', '0', '0', '0'};
56	        out[0] = clean.charAt(0);
57	        char last = codeAt(clean, 0);
58	        int count = 1;
59	        for (int i = 1; i < clean.length() && count < out.length; i++) {
60	            char mapped = codeAt(clean, i);
61	            if (mapped != 0) {
62	                if (mapped != '0' && mapped != last) {
63	                    out[count++] = mapped;
64	                }
65	                last = mapped;
66	            }
67	        }
68	        return new String(out);
69	    }
70	
71	    /**
72	     * The Soundex code digit of the letter at {@code index}, applying the H/W rule: a letter whose
73	     * code matches the letter two positions back is suppressed (returns {@code (char) 0}) when the
74	     * intervening letter is {@code H} or {@code W}, so such a pair contributes a single digit.
75	     *
76	     * @param str a cleaned, upper-case, letters-only name
77	     * @param index the position of the letter to code
78	     * @return the mapped code digit, or {@code (char) 0} when the letter is suppressed by the H/W rule
79	     */
80	    private static char codeAt(String str, int index) {
81	        char mapped = MAPPING[str.charAt(index) - 'A'];
82	        if (index > 1 && mapped != '0') {
83	            char hw = str.charAt(index - 1);
84	            if (hw == 'H' || hw == 'W') {
85	                char preHW = str.charAt(index - 2);
86	                if (MAPPING[preHW - 'A'] == mapped || preHW == 'H' || preHW == 'W') {
87	                    return 0;
88	                }
89	            }
90	        }
91	        return mapped;
92	    }
93	
94	}
